mapper.select:
SELECT s.id AS id, s.brief AS brief, s.image AS image, s.create_time AS create_time, s.content_type AS content_type, IFNULL(browse_count.browse_count, 0) AS browse_count, IFNULL(like_count.like_count, 0) AS like_count FROM share s LEFT JOIN ( SELECT post_id, COUNT(*) AS browse_count FROM browse WHERE type = 1 GROUP BY post_id ) browse_count ON s.id = browse_count.post_id LEFT JOIN ( SELECT target_id AS post_id, COUNT(*) AS like_count FROM likes WHERE type = 1 AND status = 0 GROUP BY target_id ) like_count ON s.id = like_count.post_id WHERE s.author_id = #{userId} AND s.status = 2
AND ( s.create_time < #{lastCreateTime} OR (s.create_time = #{lastCreateTime} AND s.id < #{lastId}) )
ORDER BY s.create_time DESC, s.id DESC LIMIT #{size}

SELECT s.id AS id, ui.user_id AS user_id, ui.user_name AS user_name, ui.image AS user_avatar, s.topic_id AS topic_id, s.brief AS brief, s.image AS image, s.create_time AS create_time, s.content_type AS content_type, IFNULL(browse_count.browse_count, 0) AS browse_count, IFNULL(like_count.like_count, 0) AS like_count FROM share s LEFT JOIN ( SELECT post_id, COUNT(*) AS browse_count FROM browse WHERE type = 1 GROUP BY post_id ) browse_count ON s.id = browse_count.post_id LEFT JOIN ( SELECT target_id AS post_id, COUNT(*) AS like_count FROM likes WHERE type = 1 AND status = 0 GROUP BY target_id ) like_count ON s.id = like_count.post_id LEFT JOIN user_info ui on ui.user_id = s.author_id WHERE s.status = 2
AND ( s.create_time < #{lastCreateTime} OR (s.create_time = #{lastCreateTime} AND s.id < #{lastId}) )
AND s.topic_id = #{topicId}
ORDER BY s.create_time DESC, s.id DESC LIMIT #{size}

select s.id as article_id, ui.user_id as user_id, ui.user_name as user_name, ui.image as avatar, s.brief as intro, s.image as cover, s.create_time as create_time from share s left join user_info ui on s.author_id = ui.user_id inner join user_focus uf on s.author_id = uf.focus_user_id where s.status = 2 and uf.user_id = #{userId}
and ( s.create_time < #{lastCreateTime} or (s.create_time = #{lastCreateTime} and s.id < #{lastTargetId}) )
order by s.create_time desc, s.id desc limit #{size}
